  const cleaned = name.trim();
  return cleaned.charAt(0).toUpperCase() + cleaned.slice(1);
};

const processContact = (contact) => ({
  name: formatName(contact.name),
  phone: contact.phone,
  validPhone: isValidPhone(contact.phone)
});

