codeExamples.code:
const startTime = Date.now();
const items = $input.all().map(i => i.json);

// Validation
const isValid = (item) => {
  const checks = {
    hasName: item.name && item.name.trim().length > 0,
    hasEmail: item.email && item.email.includes('@'),
    validLength: item.name && item.name.length <= 100
  };
  return Object.values(checks).every(Boolean);
};

// Processing
const results = items.map((item, idx) => {
  if (!isValid(item)) {
    return { type: 'error', data: item, reason: 'validation_failed' };
  }

  return {
    type: 'success',
    data: {
      id: Date.now() + idx,
      name: item.name.trim().toLowerCase(),
      email: item.email.trim().toLowerCase(),
      processed: new Date().toISOString()
    }
  };
});

const successful = results.filter(r => r.type === 'success');
const failed = results.filter(r => r.type === 'error');
const duration = Date.now() - startTime;

return [{
  json: {
    items: successful.map(r => r.data),
    summary: {
      total: items.length,
      successful: successful.length,
      failed: failed.length,
      duration: `${duration}ms`,
      successRate: `${(successful.length/items.length*100).toFixed(1)}%`
    },
    errors: failed.map(r => ({ data: r.data, reason: r.reason }))
  }
}];

