// Function node: Categorize and route orders
const order = $json;

// Complex conditional logic
let category, priority, processingTime;

if (order.amount > 5000 && order.customer.type === 'enterprise') {
  category = 'vip';
  priority = 1;
  processingTime = '2-hours';
  order.assignedTeam = 'enterprise';
  order.requiresApproval = true;

} else if (order.amount > 1000 || order.isUrgent) {
  category = 'priority';
  priority = 2;
  processingTime = '24-hours';
  order.assignedTeam = 'priority';
  order.requiresApproval = order.amount > 2500;

} else if (order.customer.isReturning) {
  category = 'loyal';
  priority = 3;
  processingTime = '48-hours';
  order.assignedTeam = 'standard';
  order.requiresApproval = false;

} else {
  category = 'standard';
  priority = 4;
  processingTime = '72-hours';
  order.assignedTeam = 'standard';
  order.requiresApproval = false;
}

// Add categorization to order
order.category = category;
order.priority = priority;
order.estimatedProcessingTime = processingTime;
order.categorizedAt = new Date().toISOString();

return [{ json: order }];

// Function node: Map API status codes to user-friendly messages
const response = $json;

let userMessage, shouldRetry, severity;

// Switch statement handles multiple discrete values elegantly
switch(response.statusCode) {
  case 200:
  case 201:
    userMessage = 'Success! Your request was processed.';
    shouldRetry = false;
    severity = 'info';
    break;

  case 400:
    userMessage = 'Invalid request. Please check your input.';
    shouldRetry = false;
    severity = 'error';
    break;

  case 401:
  case 403:
    userMessage = 'Authentication failed. Please log in again.';
    shouldRetry = false;
    severity = 'warning';
    break;

  case 429:
    userMessage = 'Too many requests. Please try again later.';
    shouldRetry = true;
    severity = 'warning';
    break;

  case 500:
  case 502:
  case 503:
    userMessage = 'Server error. We\'ll retry automatically.';
    shouldRetry = true;
    severity = 'error';
    break;

  default:
    userMessage = `Unexpected response: ${response.statusCode}`;
    shouldRetry = true;
    severity = 'warning';
}

return [{
  json: {
    ...response,
    userMessage,
    shouldRetry,
    severity,
    processedAt: new Date().toISOString()
  }
}];

