// Email classification logic
const email = $json;

// Check conditions
const isVIP = email.sender.endsWith('vip.com');
const subjectUpper = email.subject.toUpperCase();
const isUrgent = subjectUpper.includes('URGENT') || 
                 subjectUpper.includes('ASAP') || 
                 subjectUpper.includes('CRITICAL');
const hasAttachments = email.hasAttachments;

// Classify with if/else
let category, priority, responseTime;

if (isVIP && isUrgent) {
  category = 'vip-urgent';
  priority = 1;
  responseTime = '1-hour';

