// Function node: Implement retry logic for API calls
const item = $json;
const maxRetries = 3;
const baseDelay = 1000; // 1 second

async function fetchWithRetry(url, retryCount = 0) {
  try {
    // Simulate API call (replace with actual fetch/axios call)
    const response = await $http.get(url);
    return { success: true, data: response.data };

  } catch (error) {
    // Check if we should retry
    if (retryCount < maxRetries) {
      // Calculate delay with exponential backoff
      const delay = baseDelay * Math.pow(2, retryCount);

      // Log retry attempt
      console.log(`Retry ${retryCount + 1}/${maxRetries} after ${delay}ms`);

      // Wait before retrying
      await new Promise(resolve => setTimeout(resolve, delay));

      // Recursive retry
      return fetchWithRetry(url, retryCount + 1);
    }

    // Max retries exceeded
    throw new Error(`Failed after ${maxRetries} retries: ${error.message}`);
  }
}

// Use the retry function
try {
  const result = await fetchWithRetry(item.apiUrl);
  return [{ json: result }];

} catch (error) {
  return [{
    json: {
      success: false,
      error: error.message,
      url: item.apiUrl,
      retriesAttempted: maxRetries,
      timestamp: new Date().toISOString()
    }
  }];
}

