const user = $json;

// Validation function
function validateUser(user) {
  const errors = [];

  // Check required fields
  if (!user.name) errors.push('Missing required field: name');
  if (!user.email) errors.push('Missing required field: email');
  if (user.age === undefined) errors.push('Missing required field: age');

  // Validate email format
  if (user.email && (!user.email.includes('@') || !user.email.includes('.'))) {
    errors.push('Invalid email format');
  }

  // Validate age
  if (user.age !== undefined) {
    if (typeof user.age !== 'number') {
      errors.push('Age must be a number');
    } else if (user.age < 0 || user.age > 150) {
      errors.push('Age must be between 0 and 150');
    }
  }

  return errors;
}

// Validate
const validationErrors = validateUser(user);
if (validationErrors.length > 0) {
  return [{
    json: {
      success: false,
      errorType: 'VALIDATION_ERROR',
      errors: validationErrors,
      receivedData: user,
      timestamp: new Date().toISOString()
    }
  }];
}

// Try to parse metadata
let metadata = null;
let metadataError = null;

if (user.metadata) {
  try {
    metadata = typeof user.metadata === 'string'
      ? JSON.parse(user.metadata)
      : user.metadata;
  } catch (error) {
    metadataError = error.message;
    // Continue processing - metadata is optional
  }
}

// Success - return enriched data
const enriched = {
  ...user,
  metadata: metadata,
  metadataError: metadataError,
  emailDomain: user.email.split('@')[1],
  ageGroup: user.age < 18 ? 'minor' : user.age < 65 ? 'adult' : 'senior',
  processedAt: new Date().toISOString(),
  validation: {
    passed: true,
    checkedFields: ['name', 'email', 'age', 'metadata']
  }
};

return [{ json: { success: true, data: enriched } }];

