// Function node: Track and prevent duplicate email processing
// Assumes 'Get Processed' node retrieves stored data
// and 'Set Processed' node will save it back

// Get previously processed email IDs from storage
const storedData = $node['Get Processed'].json;
const processedIds = storedData.processedIds || [];

// Get current incoming emails
const incomingEmails = $input.all().map(item => item.json);

// Filter out emails we've already processed
const newEmails = incomingEmails.filter(email => {
  return !processedIds.includes(email.id);
});

// If no new emails, return empty
if (newEmails.length === 0) {
  return [{
    json: {
      message: 'No new emails to process',
      totalReceived: incomingEmails.length,
      alreadyProcessed: incomingEmails.length
    }
  }];
}

// Add new email IDs to processed list
const newIds = newEmails.map(email => email.id);
const updatedProcessedIds = [...processedIds, ...newIds];

// Keep only last 1000 IDs to prevent unlimited growth
const trimmedIds = updatedProcessedIds.slice(-1000);

// Return:
// 1. New emails to process (as separate items)
// 2. Updated storage data
return [
  ...newEmails.map(email => ({ json: email })),
  {
    json: {
      _storage: true,
      processedIds: trimmedIds,
      lastUpdated: new Date().toISOString(),
      totalTracked: trimmedIds.length
    }
  }
];

// Function node: Implement hourly API rate limiting
// Tracks API calls per hour and enforces limits

// Get counter from storage
const stored = $node['Get Counter'].json;
const now = new Date();
const currentHour = now.getHours();
const currentDate = now.toISOString().split('T')[0];

// Initialize or reset counter if new hour
let counter = stored.counter || {};
const counterKey = `${currentDate}-${currentHour}`;

if (!counter[counterKey]) {
  // New hour - reset counter
  counter = { [counterKey]: 0 };

  // Clean up old hours (keep only current)
  // This prevents counter object from growing indefinitely
}

// Check rate limit
const maxCallsPerHour = 100;
const currentCalls = counter[counterKey];

if (currentCalls >= maxCallsPerHour) {
  return [{
    json: {
      success: false,
      error: 'Rate limit exceeded',
      limit: maxCallsPerHour,
      currentCalls: currentCalls,
      resetTime: `${currentHour + 1}:00`,
      timestamp: now.toISOString()
    }
  }];
}

// Increment counter
counter[counterKey]++;

// Return: allow request + updated counter
return [
  {
    json: {
      allowed: true,
      remaining: maxCallsPerHour - counter[counterKey],
      resetTime: `${currentHour + 1}:00`,
      requestData: $json
    }
  },
  {
    json: {
      _storage: true,
      counter: counter,
      lastUpdated: now.toISOString()
    }
  }
];

// Function node: Cache API responses with TTL
const request = $json;
const cacheKey = request.url;
const cacheDuration = 5 * 60 * 1000; // 5 minutes in milliseconds

// Get cache from storage
const stored = $node['Get Cache'].json;
const cache = stored.cache || {};

// Check if cached data exists and is still valid
if (cache[cacheKey]) {
  const cached = cache[cacheKey];
  const age = Date.now() - cached.timestamp;

  if (age < cacheDuration) {
    // Cache hit - return cached data
    return [{
      json: {
        data: cached.data,
        cacheHit: true,
        cachedAt: new Date(cached.timestamp).toISOString(),
        expiresIn: Math.round((cacheDuration - age) / 1000) + ' seconds'
      }
    }];
  }
}

// Cache miss - need to fetch fresh data
// This would trigger the next node to make the API call
return [{
  json: {
    cacheHit: false,
    needsFetch: true,
    cacheKey: cacheKey,
    url: request.url
  }
}];

// After API call, another Function node would store the response:
// cache[cacheKey] = {
//   data: apiResponse,
//   timestamp: Date.now()
// };

