// Function node: Extract and validate JSON from AI response
const aiResponse = $json.response;

// AI often wraps JSON in markdown code blocks or adds explanation
// Try multiple extraction methods
function extractJSON(text) {
  // Method 1: Look for markdown JSON code block
  const markdownMatch = text.match(/```json\s*([\s\S]*?)\s*```/);
  if (markdownMatch) return markdownMatch[1];

  // Method 2: Look for JSON object pattern
  const jsonMatch = text.match(/\{[\s\S]*\}/);
  if (jsonMatch) return jsonMatch[0];

  // Method 3: Try the entire text
  return text;
}

try {
  const jsonStr = extractJSON(aiResponse);
  const parsed = JSON.parse(jsonStr);

  // Validate required fields
  const requiredFields = ['summary', 'category', 'action_items'];
  const missingFields = requiredFields.filter(field => !parsed[field]);

  if (missingFields.length > 0) {
    return [{
      json: {
        success: false,
        error: 'Missing required fields',
        missingFields,
        partialData: parsed
      }
    }];
  }

  // Success - return structured data
  return [{
    json: {
      success: true,
      data: parsed,
      metadata: {
        extractedAt: new Date().toISOString(),
        originalLength: aiResponse.length
      }
    }
  }];

} catch (error) {
  // Parsing failed - return error with original response
  return [{
    json: {
      success: false,
      error: 'JSON parsing failed',
      errorMessage: error.message,
      rawResponse: aiResponse
    }
  }];
}

// Function node: Parse action items from AI-generated text
const aiResponse = $json.response;

// Extract lines that look like action items
// Common patterns: start with -, *, number, or action verbs
const lines = aiResponse.split('\n').map(line => line.trim());

const actionItems = [];
let currentSection = null;

lines.forEach(line => {
  // Detect section headers (e.g., "Action Items:", "TODO:")
  if (line.toLowerCase().includes('action') || line.toLowerCase().includes('todo')) {
    currentSection = 'actions';
    return;
  }

  // Skip empty lines
  if (!line) return;

  // Extract items based on patterns
  if (currentSection === 'actions') {
    // Remove common prefixes
    let item = line.replace(/^[-*•]\s*/, '') // bullets
                    .replace(/^\d+[\.\)]\s*/, ''); // numbers

    if (item.length > 0) {
      // Detect priority (if marked with !, !!, or HIGH/MEDIUM/LOW)
      let priority = 'normal';
      if (item.includes('!!') || item.toUpperCase().includes('URGENT')) {
        priority = 'high';
        item = item.replace(/!+/g, '').replace(/urgent/gi, '').trim();
      } else if (item.includes('!') || item.toUpperCase().includes('HIGH')) {
        priority = 'medium';
        item = item.replace(/!/g, '').replace(/high/gi, '').trim();
      }

      // Detect due date patterns (e.g., "by Friday", "tomorrow", "2024-01-15")
      const dueDateMatch = item.match(/by\s+(\w+|\d{4}-\d{2}-\d{2})/i);
      const dueDate = dueDateMatch ? dueDateMatch[1] : null;

      actionItems.push({
        item: item,
        priority: priority,
        dueDate: dueDate,
        createdAt: new Date().toISOString()
      });
    }
  }
});

return [{
  json: {
    actionItems: actionItems,
    count: actionItems.length,
    rawResponse: aiResponse
  }
}];

