  if (trimmed.toLowerCase().includes('summary:')) {
    inSummary = true;
    inActions = false;
  } else if (trimmed.toLowerCase().includes('action')) {
    inActions = true;
    inSummary = false;
  } else if (inSummary && trimmed) {
    summary += trimmed + ' ';
  } else if (inActions && (trimmed.startsWith('-') || trimmed.startsWith('*'))) {
    actionItems.push(trimmed.replace(/^[-*]\s*/, ''));
  }
});

return [{ json: { summary: summary.trim(), actionItems, count: actionItems.length } }];

