// Function node: Manage multi-turn conversation
// Assumes you have a 'Get History' node that retrieves stored conversation
const conversationHistory = $node['Get History'].json.messages || [];
const userMessage = $json.userMessage;
const userId = $json.userId;

// Create new message object
const newMessage = {
  role: 'user',
  content: userMessage,
  timestamp: new Date().toISOString(),
  userId: userId
};

// Add to history and implement sliding window (keep last 10 messages)
const updatedHistory = [...conversationHistory, newMessage].slice(-10);

// Estimate total tokens (rough calculation: 1 token ≈ 4 characters)
const totalChars = updatedHistory.reduce((sum, msg) => sum + msg.content.length, 0);
const estimatedTokens = Math.ceil(totalChars / 4);

// Format for AI API (OpenAI format)
const messagesForAI = updatedHistory.map(msg => ({
  role: msg.role,
  content: msg.content
}));

return [{
  json: {
    messages: updatedHistory,
    messagesForAI: messagesForAI,
    metadata: {
      messageCount: updatedHistory.length,
      estimatedTokens: estimatedTokens,
      userId: userId,
      lastUpdated: new Date().toISOString()
    }
  }
}];

// Function node: Trim history based on token budget
const messages = $json.messages;
const maxTokens = 3000; // Safe limit for GPT-3.5

// More accurate token estimation
function estimateTokens(text) {
  // Count words and punctuation as rough token estimate
  const words = text.split(/\s+/).length;
  const chars = text.length;
  return Math.max(words, Math.ceil(chars / 4));
}

// Build history from newest to oldest, staying within budget
const trimmedMessages = [];
let tokenCount = 0;

// Always keep system message if exists
const systemMsg = messages.find(m => m.role === 'system');
if (systemMsg) {
  trimmedMessages.push(systemMsg);
  tokenCount += estimateTokens(systemMsg.content);
}

// Add messages from newest to oldest until we hit token limit
for (let i = messages.length - 1; i >= 0; i--) {
  const msg = messages[i];
  if (msg.role === 'system') continue; // Already added

  const msgTokens = estimateTokens(msg.content);

  if (tokenCount + msgTokens <= maxTokens) {
    trimmedMessages.unshift(msg); // Add to beginning to maintain order
    tokenCount += msgTokens;
  } else {
    break; // Stop if we'd exceed limit
  }
}

return [{
  json: {
    messages: trimmedMessages,
    stats: {
      originalCount: messages.length,
      trimmedCount: trimmedMessages.length,
      estimatedTokens: tokenCount,
      droppedMessages: messages.length - trimmedMessages.length
    }
  }
}];

