  createdAt: new Date().toISOString()
};

// Optional: Limit cache size (keep last 100 entries)
const cacheKeys = Object.keys(cacheStore);
if (cacheKeys.length > 100) {
  // Sort by timestamp and keep newest 100
  const sortedKeys = cacheKeys.sort((a, b) => 
    cacheStore[b].timestamp - cacheStore[a].timestamp
  );

  const newCacheStore = {};
  sortedKeys.slice(0, 100).forEach(key => {
    newCacheStore[key] = cacheStore[key];
  });

  return [{
    json: {
      cacheStore: newCacheStore,
      response: aiResponse,
      cached: true,
      entriesRemoved: cacheKeys.length - 100
    }
  }];
}

return [{
