// Function node: Different TTLs based on query type
const query = $json.query;
const queryType = $json.type || 'general';
const cached = $json.cached;

// Define TTLs for different query types
const TTL_CONFIG = {
  'weather': 10 * 60 * 1000,      // 10 minutes - changes frequently
  'news': 30 * 60 * 1000,         // 30 minutes
  'general': 60 * 60 * 1000,      // 1 hour - stable information
  'facts': 24 * 60 * 60 * 1000    // 24 hours - rarely changes
};

const ttl = TTL_CONFIG[queryType] || TTL_CONFIG['general'];

if (cached && cached.timestamp) {
  const age = Date.now() - cached.timestamp;
  const isValid = age < ttl;

  return [{
    json: {
      response: isValid ? cached.response : null,
      cacheStatus: isValid ? 'HIT' : 'EXPIRED',
      ttl: ttl,
      age: age,
      queryType: queryType,
      needsRefresh: !isValid
    }
  }];
}

return [{
  json: {
    cacheStatus: 'MISS',
    queryType: queryType,
    ttl: ttl,
    needsRefresh: true
  }
}];

// Function node: Track cache performance metrics
