const stats = $node['Get Cache Stats'].json || {
  hits: 0,
  misses: 0,
  expired: 0,
  totalRequests: 0,
  costSaved: 0
};

// Update statistics
stats.totalRequests++;

if (cacheResult === 'HIT') {
  stats.hits++;
  stats.costSaved += 0.002; // Approximate cost per AI call
} else if (cacheResult === 'MISS') {
  stats.misses++;
} else if (cacheResult === 'EXPIRED') {
  stats.expired++;
}

// Calculate hit rate
const hitRate = ((stats.hits / stats.totalRequests) * 100).toFixed(2);

// Calculate efficiency
const efficiency = {
  hitRate: `${hitRate}%`,
  totalSaved: `$${stats.costSaved.toFixed(4)}`,
  avgCostPerRequest: stats.totalRequests > 0 
    ? `$${((stats.costSaved) / stats.totalRequests).toFixed(6)}`
    : '$0'
};

return [{
  json: {
    stats: stats,
    efficiency: efficiency,
    recommendation: parseFloat(hitRate) < 30 
      ? 'Consider increasing TTL or improving cache key strategy'
      : 'Cache performing well'
  }
}];

