# Common AI code patterns to recognize

import time
from openai import OpenAI, RateLimitError

client = OpenAI()

def call_with_retry(messages, max_retries=3):
    """Pattern: Retry logic for rate limits."""
    for attempt in range(max_retries):
        try:
            response = client.chat.completions.create(
                model="gpt-3.5-turbo",
                messages=messages
            )
            return response
        except RateLimitError:
            if attempt < max_retries - 1:
                wait_time = 2 ** attempt  # Exponential backoff
                time.sleep(wait_time)
            else:
                raise

# Pattern: Streaming responses
def stream_response(messages):
    """Pattern: Stream tokens as they arrive."""
    stream = client.chat.completions.create(
        model="gpt-3.5-turbo",
        messages=messages,
        stream=True  # Enable streaming
    )

    for chunk in stream:
        if chunk.choices[0].delta.content:
            print(chunk.choices[0].delta.content, end="")

# Pattern: Token counting before API call
import tiktoken

def count_tokens(text, model="gpt-3.5-turbo"):
    """Pattern: Count tokens to avoid limits."""
    encoding = tiktoken.encoding_for_model(model)
    return len(encoding.encode(text))

