codeExamples.code:
from fastapi import FastAPI
import logging
import time

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(message)s')
app = FastAPI()
rag = RAGSystem()

@app.post('/ingest')
def ingest(request: dict):
    try:
        result = rag.ingest(request['file_path'])
        logging.info(f'Ingested: {request['file_path']}, chunks: {result['chunks_created']}')
        return result
    except Exception as e:
        logging.error(f'Ingestion failed: {str(e)}')
        return {'status': 'error', 'message': str(e)}

@app.post('/query')
def query(request: dict):
    start = time.time()
    try:
        result = rag.query(request['question'])
        latency = time.time() - start
        logging.info(f'Query: {request['question'][:50]}, latency: {latency:.2f}s')
        return {**result, 'latency_seconds': latency}
    except Exception as e:
        logging.error(f'Query failed: {str(e)}')
        return {'status': 'error', 'message': str(e)}

if __name__ == '__main__':
    import uvicorn
    uvicorn.run(app, host='0.0.0.0', port=8000)

